import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * Secure implementation of an Atom provider. The {@code readFrom} method now creates a
 * dedicated {@link Parser} instance for each request and configures it with
 * {@link ParserOptions} that explicitly disable external entity resolution and DTD
 * processing, eliminating the XXE attack surface.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // -----------------------------------------------------------------------
    //  Secure readFrom implementation
    // -----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type genericType,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // -------------------------------------------------------------------
        //  1. Build parser options that are safe against XXE.
        // -------------------------------------------------------------------
        ParserOptions safeOptions = new ParserOptions();
        safeOptions.setAutodetectCharset(autodetectCharset);
        // Disable external entity resolution (core XXE mitigation)
        safeOptions.setResolveEntities(false);
        // Disallow DTDs – additional hardening (available in recent Abdera versions)
        safeOptions.setSupportDTD(false);

        // -------------------------------------------------------------------
        //  2. Obtain a fresh parser instance for this request.
        // -------------------------------------------------------------------
        Parser parser = ATOM_ENGINE.getParserFactory().newParser();
        parser.setParserOptions(safeOptions);

        // -------------------------------------------------------------------
        //  3. Parse the input safely and ensure the stream is closed.
        // -------------------------------------------------------------------
        Document<T> document;
        try {
            document = parser.parse(entityStream);
        } finally {
            // Close the stream to avoid resource leaks; ignore secondary errors.
            try {
                entityStream.close();
            } catch (IOException ignored) {
                // Logging could be added here in a real production environment.
            }
        }

        // -------------------------------------------------------------------
        //  4. Return the root element of the parsed document.
        // -------------------------------------------------------------------
        return document.getRoot();
    }

    // other methods (writeTo, etc.) remain unchanged
}
