static public File allocateFile(File dir, String name) {
    if (dir == null) {
        throw new IllegalArgumentException("Target directory must not be null");
    }
    if (name == null) {
        throw new IllegalArgumentException("File name must not be null");
    }

    // Strip any URL query part
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }

    // Disallow path separators to avoid creating sub‑directories unintentionally
    if (name.contains("/") || name.contains("\\") || name.contains(File.separator)) {
        throw new IllegalArgumentException("File name must not contain path separators");
    }

    // Build the initial file object
    File file = new File(dir, name);
    try {
        // Resolve both paths to their canonical (real) form and verify containment
        File canonicalDir = dir.getCanonicalFile();
        File canonicalFile = file.getCanonicalFile();
        if (!canonicalFile.toPath().startsWith(canonicalDir.toPath())) {
            throw new IllegalArgumentException("Resulting file escapes the target directory");
        }
    } catch (IOException e) {
        throw new IllegalArgumentException("Unable to resolve file paths", e);
    }

    // Determine base name and extension for duplicate handling
    int dot = name.lastIndexOf('.');
    String prefix = dot < 0 ? name : name.substring(0, dot);
    String suffix = dot < 0 ? "" : name.substring(dot);
    int index = 2;
    while (file.exists()) {
        file = new File(dir, prefix + "-" + index++ + suffix);
        try {
            // Re‑check after each iteration in case the new name somehow escapes the dir
            if (!file.getCanonicalFile().toPath().startsWith(dir.getCanonicalFile().toPath())) {
                throw new IllegalArgumentException("Generated file name escapes the target directory");
            }
        } catch (IOException e) {
            throw new IllegalArgumentException("Unable to resolve file paths", e);
        }
    }

    // Ensure the parent directory exists
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IllegalStateException("Failed to create directory: " + parent);
    }

    return file;
}
