    // FactoryBean contract
    // -----------------------------------------------------------------------

    @Override
    public SecureRandom getObject() throws Exception {
        SecureRandom rnd = createSecureRandomInstance();
        // Warm‑up the generator – forces any lazy internal seeding.
        rnd.nextBytes(new byte[1]);
        return rnd;
    }

    @Override
    public Class<?> getObjectType() {
        return SecureRandom.class;
    }

    @Override
    public boolean isSingleton() {
        // SecureRandom instances are not thread‑safe for mutation, so we expose a new
        // instance each time to avoid shared mutable state.
        return false;
    }

