private static void decompress(final InputStream in, final byte[] out) throws IOException {
    if (in == null) {
        throw new IllegalArgumentException("InputStream must not be null");
    }
    if (out == null) {
        throw new IllegalArgumentException("Output buffer must not be null");
    }

    int position = 0;
    final int total = out.length;

    while (position < total) {
        // read control byte; -1 indicates premature end of stream
        final int control = in.read();
        if (control == -1) {
            throw new EOFException("Unexpected end of compressed data while reading control byte");
        }

        // Determine how many bytes we have to write
        final int count;
        final int value; // only used for run‑length case

        if (control > 128) {
            // run‑length encoded block
            count = control & 0x7F; // number of repetitions
            // read the byte that will be repeated
            final int repeat = in.read();
            if (repeat == -1) {
                throw new EOFException("Unexpected end of compressed data while reading repeat value");
            }
            value = repeat;
        } else {
            // literal block
            count = control;
            value = -1; // not used
        }

        // Defensive check: never write past the supplied buffer
        if (position + count > total) {
            throw new IOException("Decompressed data exceeds expected size (position=" + position +
                    ", count=" + count + ", total=" + total + ")");
        }

        if (control > 128) {
            // fill with the repeated value
            for (int i = 0; i < count; i++) {
                out[position++] = (byte) value;
            }
        } else {
            // copy literal bytes
            for (int i = 0; i < count; i++) {
                final int b = in.read();
                if (b == -1) {
                    throw new EOFException("Unexpected end of compressed data while reading literal byte");
                }
                out[position++] = (byte) b;
            }
        }
    }
}
