/**
 * Extends the value {@code v} that was read using {@code t} bits to a signed integer.
 * This method follows the JPEG specification for the "extend" operation.
 *
 * <p>The original implementation used a {@code while} loop that recomputed {@code vt}
 * on each iteration, which could lead to an infinite loop for malformed inputs
 * (e.g., {@code t == 0} or crafted values of {@code v}).  The corrected version
 * validates the parameters and performs the extension in a single, deterministic
 * step.</p>
 *
 * @param v the raw value read (unsigned) using {@code t} bits
 * @param t the number of bits that were used to read {@code v}
 * @return the sign‑extended integer value
 * @throws IllegalArgumentException if {@code t} is outside the range 1‑31
 */
private int extend(int v, final int t) {
    // JPEG defines that a bit length of 0 yields a value of 0.
    if (t == 0) {
        return 0;
    }

    // Guard against illegal shift amounts (Java shifts mask the shift count,
    // so values >31 would produce incorrect results).
    if (t < 0 || t > 31) {
        throw new IllegalArgumentException("Bit length 't' must be between 0 and 31 inclusive, but was: " + t);
    }

    // Compute the threshold for the sign bit.
    int vt = 1 << (t - 1);

    // If the most‑significant bit is not set, the value is negative and must be
    // sign‑extended. The original loop attempted to achieve this by repeatedly
    // adding a correction factor; a single correction is sufficient.
    if (v < vt) {
        v += (-1 << t) + 1;   // Equivalent to v - (1 << t) + 1
    }

    return v;
}
