public class WebUtils {

    public static final String INCLUDE_CONTEXT_PATH_ATTRIBUTE = "javax.servlet.include.context_path";

    // ---------------------------------------------------------------------
    // Patched getContextPath implementation
    // ---------------------------------------------------------------------

    /**
     * Return the context path for the given request, detecting an include request
     * URL if called within a {@code RequestDispatcher} include.
     * <p>
     * The returned value is decoded, cleaned and strictly validated to prevent
     * manipulation of the context path (e.g. path‑traversal, illegal characters,
     * or malformed values) that could be used to bypass servlet filters.
     *
     * @param request current HTTP request
     * @return a safe, decoded context path (empty string for the root context)
     */
    public static String getContextPath(HttpServletRequest request) {
        // 1. Obtain the raw context path – either from an include attribute or
        //    directly from the request.
        String rawContextPath = (String) request.getAttribute(INCLUDE_CONTEXT_PATH_ATTRIBUTE);
        if (rawContextPath == null) {
            rawContextPath = request.getContextPath();
        }
        if (rawContextPath == null) {
            rawContextPath = "";
        }

        // 2. Jetty (and some containers) may return "/" for an include; treat it as root.
        if ("/".equals(rawContextPath)) {
            rawContextPath = "";
        }

        // 3. Decode the raw value using the request's character encoding.
        String decoded = decodeRequestString(request, rawContextPath);

        // 4. Clean the decoded value – strip any path‑parameter part after ';'.
        String cleaned = decodeAndCleanUriString(request, decoded);

        // 5. Normalise the path (removes "./", resolves "../", collapses duplicate slashes).
        String normalized = normalize(cleaned);

        // 6. Validate the normalised context path against a strict whitelist.
        if (!isValidContextPath(normalized)) {
            // If the value is malformed we fall back to the empty (root) context.
            // This prevents an attacker from injecting a crafted value that could
            // bypass security checks based on the context path.
            normalized = "";
        }

        return normalized;
    }

    // ---------------------------------------------------------------------
    // Helper: strict validation of a context path
    // ---------------------------------------------------------------------

    /**
     * Validate that a context path conforms to the servlet specification:
     * <ul>
     *   <li>empty string for the root context, or</li>
     *   <li>starts with a single '/' followed by one or more characters that are
     *       not '/' and do not contain path‑traversal sequences.</li>
     * </ul>
     *
     * @param path the normalised context path
     * @return {@code true} if the path is safe, {@code false} otherwise
     */
    private static boolean isValidContextPath(String path) {
        // Empty string is allowed (root context)
        if (path.isEmpty()) {
            return true;
        }

        // Must start with '/' and must not end with '/' (except root)
        if (!path.startsWith("/") || path.endsWith("/")) {
            return false;
        }

