        // iteration – either the encoder consumes at least one character or the
        // buffer is grown. This prevents an infinite loop when the encoder
        // repeatedly reports unmappable/malformed input.
        while (cb.hasRemaining()) {
            CoderResult res = enc.encode(cb, out, false);

            if (res.isUnderflow()) {
                // All remaining input has been consumed.
                break;
            } else if (res.isOverflow()) {
                // Not enough space in the output buffer – grow it.
                int increment = estimateIncrementalEncodingSize(enc, cb.remaining());
                out = ZipEncodingHelper.growBufferBy(out, increment);
            } else if (res.isUnmappable() || res.isMalformed()) {
                // The encoder cannot represent the current character(s). Encode each
                // problematic character as a surrogate (percent‑encoded) sequence.
                int length = res.length();

                // Ensure there is enough room for the surrogate representation.
                int needed = estimateIncrementalEncodingSize(enc, 6 * length);
                if (needed > out.remaining()) {
                    out = ZipEncodingHelper.growBufferBy(out, needed - out.remaining());
