public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    /** Acceptable locale pattern: language (2‑3 letters) optionally "_country" (2 letters) optionally "_variant". */
    private static final Pattern LOCALE_PATTERN = Pattern.compile("^[a-zA-Z]{2,3}(_[a-zA-Z]{2})?(_[a-zA-Z0-9]+)?$");

    /** Cache of all locales that the JVM recognises – used as a whitelist. */
    private static final Set<String> VALID_LOCALE_STRINGS = new HashSet<String>();
    static {
        for (Locale l : Locale.getAvailableLocales()) {
            // Locale.toString() yields language[_country[_variant]]
            VALID_LOCALE_STRINGS.add(l.toString());
        }
    }

    // -----------------------------------------------------------------------
    // other interceptor methods …
    // -----------------------------------------------------------------------

    /**
     * Creates a {@link Locale} object from the request parameter, which might
     * already be a {@link Locale} or a {@link String}. The input is validated
     * against a strict whitelist to prevent injection attacks (e.g., XSS).
     *
     * @param requestedLocale the parameter from the request
     * @return a safe {@link Locale} instance or {@code null} if the input is
     *         invalid / not supplied
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        // 1) Already a Locale – trusted, just return it.
        if (requestedLocale instanceof Locale) {
            Locale locale = (Locale) requestedLocale;
            LOG.debug("Applied request locale (already Locale): {}", locale);
            return locale;
        }

        // 2) Accept only String values; other object types are ignored.
        if (!(requestedLocale instanceof String)) {
            LOG.warn("Unsupported type for locale parameter: {}", requestedLocale.getClass().getName());
            return null;
        }

        String localeStr = ((String) requestedLocale).trim();

        // Empty strings are treated as “no locale supplied”.
        if (localeStr.isEmpty()) {
            LOG.debug("Requested locale string is empty");
            return null;
        }

        // 3) Validate format against the whitelist pattern.
        if (!LOCALE_PATTERN.matcher(localeStr).matches()) {
            LOG.warn("Invalid locale format received: {}", localeStr);
            return null;
        }

        // 4) Convert the string to a Locale using the existing utility.
        Locale locale = LocalizedTextUtil.localeFromString(localeStr, null);
        if (locale == null) {
            LOG.warn("Unable to parse locale string: {}", localeStr);
            return null;
        }

        // 5) Ensure the resulting Locale is one of the JVM‑supported locales.
        if (!VALID_LOCALE_STRINGS.contains(locale.toString())) {
            LOG.warn("Locale not recognised by the JVM: {}", locale);
            return null;
        }

        LOG.debug("Applied request locale: {}", locale);
        return locale;
    }

    // -----------------------------------------------------------------------
    // other interceptor methods …
    // -----------------------------------------------------------------------
