    @Activate
    @SuppressWarnings("unused")
    protected void activate() {
        // Create a new factory instance and harden it against XXE attacks
        SAXParserFactory f = SAXParserFactory.newInstance();
        try {
            // Disallow DOCTYPE declarations
            f.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            // Disable external general entities
            f.setFeature("http://xml.org/sax/features/external-general-entities", false);
            // Disable external parameter entities
            f.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            // Do not load external DTDs
            f.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            // Do not load DTD grammar
            f.setFeature("http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
            // Enable secure processing
            f.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        } catch (ParserConfigurationException | SAXNotRecognizedException | SAXNotSupportedException e) {
            // If any of the hardening features cannot be set, log the problem and fall back to a safe default
            LOG.severe("Failed to configure SAXParserFactory securely: " + e.getMessage());
            // In a production environment we prefer to fail fast rather than continue with an insecure parser
            throw new IllegalStateException("Unable to securely configure SAXParserFactory", e);
        }

        // Apply the remaining non‑security‑related settings
        f.setValidating(false);
        f.setNamespaceAware(true);
        f.setXIncludeAware(false);

        // Replace the injected factory with the hardened instance
        this.factory = f;
    }

    // other methods
}
