private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Validate parameters as per InputStream contract
    if (buffer == null) {
        throw new NullPointerException("buffer");
    }
    if (offset < 0 || length < 0 || offset + length > buffer.length) {
        throw new IndexOutOfBoundsException();
    }
    if (length == 0) {
        return 0;
    }

    // If the entry uses a data descriptor we have already cached the whole entry.
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry(); // fills lastStoredEntry
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize(); // may be -1 if unknown / malformed
    // When size is known, signal EOF once we have read the declared amount.
    if (csize >= 0 && current.bytesRead >= csize) {
        return -1;
    }

    // Fill internal buffer if exhausted.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        final int l = in.read(buf.array());
        // Treat any non‑positive read as end‑of‑stream to avoid infinite loops
        if (l <= 0) {
            return -1;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;
    }

    // Determine how many bytes we can safely return.
    int toRead = Math.min(buf.remaining(), length);
    if (csize >= 0) {
        long remaining = csize - current.bytesRead;
        if (remaining <= 0) {
            return -1;
        }
        if (remaining < toRead) {
            toRead = (int) remaining;
        }
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}
