final static private XMLStreamReader createXMLStreamReader(InputStream inputStream) throws XMLStreamException, IOException {
    if (inputStream == null) {
        throw new IllegalArgumentException("InputStream must not be null");
    }
    XMLInputFactory factory = XMLInputFactory.newInstance();
    // Secure configuration against XXE
    try {
        factory.setProperty(XMLInputFactory.SUPPORT_DTD, false);
    } catch (IllegalArgumentException | IllegalStateException e) {
        // Some implementations may not support the property; ignore if not supported
    }
    try {
        factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, false);
    } catch (IllegalArgumentException | IllegalStateException e) {
        // ignore
    }
    // Desired parsing behaviour
    factory.setProperty(XMLInputFactory.IS_COALESCING, true);
    factory.setProperty(XMLInputFactory.IS_REPLACING_ENTITY_REFERENCES, true);
    // Ensure namespace awareness (optional but recommended)
    try {
        factory.setProperty(XMLInputFactory.IS_NAMESPACE_AWARE, true);
    } catch (IllegalArgumentException | IllegalStateException ignored) {}

    // Wrap the stream to avoid premature closing by the parser
    InputStream safeStream = wrapPrefixRemovingInputStream(inputStream);
    return factory.createXMLStreamReader(safeStream);
}
