import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;
import java.util.Objects;

/**
 * Checks whether a self‑update request for a {@link ScimUser} is allowed.
 *
 * <p>The original implementation only compared the values in the request body
 * with the values stored in the database.  It failed to verify that the
 * caller is actually the owner of the account being modified, which allowed
 * an attacker to change another user's e‑mail address (or other fields) by
 * simply sending a crafted request.</p>
 *
 * <p>The patched version adds a strict authorization check:
 * <ul>
 *   <li>The authenticated principal (extracted from {@code request.getUserPrincipal()})
 *       must be present.</li>
 *   <li>The principal's identifier must match the user id extracted from the
 *       request URL (the {@code id} path variable).</li>
 *   <li>If the check fails, the method returns {@code false} immediately,
 *       preventing any further processing.</li>
 * </ul>
 *
 * <p>All subsequent field‑by‑field comparisons now use {@link Objects#equals}
 * to guard against {@code null} values and avoid {@link NullPointerException}s.</p>
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Determines whether the incoming request is allowed to modify the user.
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the request is authorized and the payload does not
     *         attempt to modify immutable fields; {@code false} otherwise
     * @throws IOException if the request body cannot be read
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        /* -------------------------------------------------------------
         * 1.  Verify that the caller is authenticated and is the owner of
         *     the account identified by the URL path variable.
         * ------------------------------------------------------------- */
        Principal principal = request.getUserPrincipal();
        if (principal == null) {
            // No authenticated principal – deny the request.
            return false;
        }

        // Extract the user id from the request URL (e.g. /Users/{id})
        String idFromPath = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // The principal name is expected to be the user id in UAA.
        String authenticatedUserId = principal.getName();
        if (!Objects.equals(authenticatedUserId, idFromPath)) {
            // The caller is trying to modify a different user – deny.
            return false;
        }

        /* -------------------------------------------------------------
         * 2.  Load the current user representation from the DB.
         * ------------------------------------------------------------- */
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(idFromPath, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist we cannot safely allow the update.
            return false;
        }

        /* -------------------------------------------------------------
         * 3.  Parse the incoming payload.
         * ------------------------------------------------------------- */
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        /* -------------------------------------------------------------
         * 4.  Validate that immutable fields have not been altered.
         *    Only fields that are allowed to change in a self‑update are
         *    compared; any mismatch results in denial.
         * ------------------------------------------------------------- */
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the update is allowed.
        return true;
    }

    // other methods …
}
